---加载指定基因猫
---@param geneId integer @ 基因id
---@param parent UnityEngine.GameObject
---@param initCallback fun(catGo:UnityEngine.GameObject, catId:string):void
function PreDownloadUtils.LoadGeneCat(geneId, parent, initCallback)
    ---@type CatHouseCatDataVo
    local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, CatHouseCatDataVo, geneId)
    
    local catId = "101"
    ---创建新的猫
    if catHouseCatDataVo.kind == ConstantsCatHouse.ScreenCatDataType.Combination then
        ---组合
        ---@type CatHouseHeritableVo
        local heritableVo = CatHouseMgr:GetInstance():GetHeritableVoByRefId(catHouseCatDataVo.id)
        catId = table.takeFirst(heritableVo.catId)
    elseif catHouseCatDataVo.kind == ConstantsCatHouse.ScreenCatDataType.Variation then
        ---@type CatHouseHeritableVo
        local heritableVo = CatHouseMgr:GetInstance():GetVariationVoByRefId(catHouseCatDataVo.id)
        catId = table.takeFirst(heritableVo.catId)
    end

    cs_coroutine.yield_return(AutoPNGWriter.LoadCatAsync(ConstantsCatHouse.BornType.Adult, catId, false, { catHouseCatDataVo.id }, parent, function(catGo)
        ---@type UnityEngine.Transform
        local trans = catGo.transform
        trans.localPosition = Vector3.New(0, 0, 0)
        trans.localRotation = Quaternion.Euler(0, 0, 0)
        trans.localScale    = Vector3.New(1, 1, 1)
        if initCallback then
            initCallback(catGo, catId)
        end
    end))
end


---初始化猫球
---@param geneId integer 基因id
function PreDownloadUtils.InitCat(geneId)
    local go = GameObject.Find("PreDownloadCameraNode")
    if isNull(go) then
        ---相机节点
        ---@type UnityEngine.GameObject
        go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.PreDownloadCameraNode)
        go.transform.localPosition = Vector3.New(1000, 1000, 1000)
    else
        local catModel = go.transform:Find("CatModel").gameObject
        KTool.DestroyGameObjectChildren(catModel)
    end

    local co = cs_coroutine.start(function()
        local catModel = go.transform:Find("CatModel").gameObject
        PreDownloadUtils.LoadGeneCat(geneId, catModel, function(catGo, catId)
            ---@type UnityEngine.Transform
            local trans = catGo.transform
            catGo.name = catId

            trans.localPosition = Vector3.New(-0.014, -0.145, 4.25)
            trans.localRotation = Quaternion.Euler(11.658, -152.876, 6.148)
            trans.localScale = Vector3.New(1, 1, 1)
        end)
    end)
    return go, co
end

---获取猫球获得排名图标地址
---@param rank integer 排名
---@return string 图标地址
function PreDownloadUtils.GetCatRankIconPath(rank)
    rank = checkInt(rank)
    ---@type PreDownloadOrderTipsVo[]
    local cf = CfUtils.GetCf(AutoIds.IdSetting2654, "PreDownloadOrderTipsVo"):GetAll()
    for i, v in ipairs(cf) do
        if rank >= checkInt(v.first) and rank <= checkInt(v.final) then
            return v.icon
        end
    end
end

---获取猫球获得排名描述
---@param rank integer 排名
---@return string 描述
function PreDownloadUtils.GetCatRankDesc(rank)
    rank = checkInt(rank)
    ---@type PreDownloadOrderTipsVo[]
    local cf = CfUtils.GetCf(AutoIds.IdSetting2654, "PreDownloadOrderTipsVo"):GetAll()
    for i, v in ipairs(cf) do
        if rank >= checkInt(v.first) and rank <= checkInt(v.final) then
            local str = v.decr
            str = string.gsub(str, '_target_num_', tostring(rank))
            return str
        end
    end
    return ''
end

