--- 获取参数表的设定值
---@param groupId integer @ 参数id
---@return string
function PreDownloadUtils.GetStoryInfo(groupId)
    groupId = checkNumber(groupId)
    ---@type TableML.TableFile
    local  tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting3105, true)
    local t = {}
    for _, row in pairs(tableFile) do
        local group = checkNumber(row:Get("group"))
        local desc = parse_localizeText(row, "desc")
        local primaryKey = row:Get("id")
        if groupId == group then
            table.insert(t, {
                id = primaryKey,
                groupId = groupId,
                desc = desc,
            })
        end
    end
    return t
end


--- 获取测试结果的猫咪id
---@param initCallback fun(catGo:UnityEngine.GameObject):void
---@param parent UnityEngine.GameObject
---@return System.Collections.IEnumerator
function PreDownloadUtils.LoadResultCatModelAsync(initCallback, parent)
    local CatHouseMgrInst    = CatHouseMgr:GetInstance()
    local PreDownloadMgrInst = PreDownloadMgr:GetInstance()
    local preDownloadComp    = PreDownloadMgrInst:GetPreDownloadComponent()
    local resultCatData      = preDownloadComp:GetCatData()
    local resultCatId        = tostring(resultCatData.catId or 102)
    if string.isEmpty(resultCatData.catId) then
        resultCatId = 102
    end
    local resultCatGenes     = checkTable(resultCatData.genes)
    ---@param catGo UnityEngine.GameObject
    CatHouseMgrInst:LoadCatModelAsync(2, resultCatId, false, resultCatGenes, parent, function(catGo)
        ---@type UnityEngine.Transform
        local trans = catGo.transform
        trans.localPosition = Vector3.New(0, 0, 0)
        trans.localRotation = Quaternion.Euler(0, 0, 0)
        trans.localScale    = Vector3.New(1, 1, 1)
        if initCallback then
            initCallback(catGo)
        end
    end)
end


function PreDownloadUtils.MakeCatGeneNameId(genes)
    local geneData = checkTable(genes)
    --local catGenes  = CatHouseMgr:GetInstance():GetAttributes(geneDatas)
    table.sort(geneData, function(aGeneId, bGeneId)
        return checkInt(aGeneId) < checkInt(bGeneId)
    end)
    return table.concat(geneData, '')
end


---@param path string
---@param onStart fun(loader:Engine.Modules.AbstractResourceLoader, go:UnityEngine.GameObject):void
---@param customPlay fun(go:UnityEngine.GameObject):void
---@param onFinish fun():void
function PreDownloadUtils.LoadAndPlayTL(path, onStart, customPlay, onFinish)
    return cs_coroutine.start(function()
        local loader = ResourceModule.GetLoaderByURL(path)

        if isNull(loader) then
            loader = ResourceModule.LoadBundleAsync(path, nil, true)
        end

        while not loader.IsCompleted do
            coroutine.yield()
        end

        if not loader.IsSuccess then
            loader:Release()
            return
        end

        local go = loader:Instantiate()
        if isNull(go) then
            loader:Release()
            return
        end
        local processor = go:GetComponentInChildren(typeof(ChapterProcessor))

        PreDownloadUtils.CalculateScreenFit(go)

        local cameraCtrl = CS.Game.Native.URP.URPCameraController.Instance
        local UniversalAdditionalCameraData = CS.UnityEngine.Rendering.Universal.UniversalAdditionalCameraData
        
        --uitop的相机
        local cam = go:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
        local data = cameraCtrl.mainCamera.gameObject:GetComponent(typeof(UniversalAdditionalCameraData))
        data.cameraStack:Add(cam)
        
        if onStart ~= nil then
            onStart(loader, go)
        end

        if customPlay ~= nil then
            customPlay(go)
        else
            processor:PlayDirector()
        end
        
        local wait = true
        processor.OnChapterFinish = function()
            wait = false
        end

        while wait do
            coroutine.yield()
        end

        data.cameraStack:Clear()
        if onFinish ~= nil then
            onFinish()
        end
    end)
end


---@param go UnityEngine.GameObject
function PreDownloadUtils.CalculateScreenFit(go)
    local tmp = go:GetComponentsInChildren(typeof(CanvasScaler))
    if isNull(tmp) then
        return
    end

    for i = 1, tmp.Length do
        local scaler = tmp[i - 1]
        KTool.CalculateScreenFit(scaler)
    end
end

