---是否显示分享按钮
function PreDownloadUtils.IsShowShareButton()
    return checkInt(PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsKeyType.SHOW_SHARE_BTN)) == 1
end

---判断是否为新玩家
function PreDownloadUtils.IsNewPlayer()
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    ---@type UserComponent
    local userComp = entity:GetComp(ECSComponentType.Constants.UserComponent)
    local lastServerId = checkNumber(userComp.userInfo.lastLoginServerId)
    local currentServerId = checkNumber(userComp.userInfo.cuurentServerId)
    if currentServerId > 0 then
        return isNull(userComp:GetServerById(currentServerId))
    end
    return lastServerId <= 0 or isNull(userComp:GetServerById(lastServerId))
end


return PreDownloadUtils
